bad.code:
CREATE INDEX orders_customer_id_idx ON orders (customer_id);
-- Takes a SHARE lock: reads continue, but every INSERT,
-- UPDATE and DELETE on orders waits until the build ends.

good.code:
-- Must not run inside a transaction block: turn off your
-- migration tool's per-migration transaction for this file.
SET lock_timeout = '5s';
CREATE INDEX CONCURRENTLY orders_customer_id_idx
  ON orders (customer_id);

-- If it fails it leaves an INVALID index behind; drop and retry:
-- DROP INDEX CONCURRENTLY orders_customer_id_idx;

bad.code:
ALTER TABLE orders ALTER COLUMN region SET NOT NULL;
-- Scans every row to check for NULLs while holding
-- ACCESS EXCLUSIVE: no reads or writes for the whole scan.

good.code:
SET lock_timeout = '5s';
-- 1. Instant: enforced for new writes, old rows not checked yet
ALTER TABLE orders
  ADD CONSTRAINT orders_region_not_null
  CHECK (region IS NOT NULL) NOT VALID;

-- 2. Scans the table under a weaker lock; reads and writes continue
ALTER TABLE orders VALIDATE CONSTRAINT orders_region_not_null;

-- 3. Uses the validated constraint as proof, so no second scan
ALTER TABLE orders ALTER COLUMN region SET NOT NULL;
ALTER TABLE orders DROP CONSTRAINT orders_region_not_null;

bad.code:
-- up
ALTER TABLE orders DROP COLUMN legacy_status;
-- down
ALTER TABLE orders ADD COLUMN legacy_status text;
-- The column comes back empty: the data is gone.
